INSERT INTO public.instagram_media (id, project_id, ig_user_id, media_id, media_type, media_product_type, caption, permalink, thumbnail_url, media_url, "timestamp", like_count, comments_count, shares_count, saved_count, reach, impressions, video_views, plays, total_interactions, last_synced_at, created_at) VALUES ('6fbef05f-b3d7-46e6-b084-08d5d689226d', 'cceb9a86-687b-4417-9b4e-d106bd8cc79c', '17841422203516856', '17960323224104440', 'VIDEO', 'REELS', 'Глаза - первая мишень диабета.👁️
Знали ли вы, что диабетическая ретинопатия - одна из главных причин слепоты среди трудоспособного населения? Самое страшное: на ранних стадиях ничего НЕ БОЛИТ.
🚩З признака, что пора бежать к офтальмологу:
1. Периодический «туман» перед глазами.
2. Темные пятна или «мушки».
3. Прямые линии кажутся волнистыми.
Но лучше не ждать симптомов!
✅Золотой стандарт: Осмотр глазного дна с расширенным зрачком - 2 раза в год.
Сохрани это видео, чтобы не потерять, и отправь тому, у кого есть диабет. Это может спасти ему зрение!
