INSERT INTO public.instagram_media (id, project_id, ig_user_id, media_id, media_type, media_product_type, caption, permalink, thumbnail_url, media_url, "timestamp", like_count, comments_count, shares_count, saved_count, reach, impressions, video_views, plays, total_interactions, last_synced_at, created_at) VALUES ('7b1bbcee-9d0c-4ad2-b449-b570c3bb087a', 'cceb9a86-687b-4417-9b4e-d106bd8cc79c', '17841422203516856', '17955065319132999', 'VIDEO', 'REELS', 'Современная диагностика и лечение-это не будущее. Это сегодня!

Мы работаем только с тем, чему доверяем сами.

Наш диагностический блок оснащён аппаратами нового поколения из США, Японии и Канады это тот уровень качества, который позволяет нам видеть больше, точнее и раньше.

Мы не просто выявляем патологию, мы анализируем каждый нанометр вашего зрительного аппарата, чтобы подобрать оптимальный путь лечения.

Ваша первая диагностика- первый шаг к тому, чтобы снова увидеть мир по-новому!

Мы рядом на каждом этапе: от обследования до восстановления зрения!

