INSERT INTO public.instagram_media (id, project_id, ig_user_id, media_id, media_type, media_product_type, caption, permalink, thumbnail_url, media_url, "timestamp", like_count, comments_count, shares_count, saved_count, reach, impressions, video_views, plays, total_interactions, last_synced_at, created_at) VALUES ('cc360a09-4331-426d-a99b-e379aa4c4142', 'cceb9a86-687b-4417-9b4e-d106bd8cc79c', '17841422203516856', '18103115288060098', 'VIDEO', 'REELS', 'Я создаю клинику,где важен ЧЕЛОВЕК, а не чек!

Где технологии соединяются с заботой, а зрение это право, а не привилегия.Офтальмология — это дело моей жизни. Я хочу, чтобы моя клиника стала местом, где человек чувствует заботу, а не просто проходит платную процедуру. Для меня важнее сам пациент, чем прибыль.

Социальная миссия
Я хочу, чтобы качественная помощь была доступна каждому. В моей клинике можно будет получить часть услуг бесплатно по системе ОСМС — консультацию, операцию. Это важно для меня, потому что я верю, что зрение — не привилегия, а право каждого.

Технологии и полный цикл
Я создаю клинику полного цикла с современным оборудованием из США, Канады и Японии. Здесь можно пройти всё — от диагностики до операции и восстановления, не обращаясь в другие места.

Главная идея
Я строю не просто клинику, а пространство доверия, технологий и человеческого тепла — место, где действительно хотят помочь.

Вы увидите этот мир по -новому!
